\begin{theorem}[Scotoma--Residuum--Schism Trichotomy]\label{ch01:thm:scotoma-pareto-trichotomy}%
\uses{ch01:def:adm-pareto-frontier}%
Let {{sym:probe-suite}} be a calibrated probe suite over $\Phi = (H, C, K)$ ({{ref:ch01:def:adm-pareto-frontier}}) whose deductive-weakening order on $\mathrm{Adm}_{{{sym:probe-suite}}}$ is well-founded. Then $\mathrm{Adm}_{{{sym:probe-suite}}}$ partitions exhaustively and disjointly into three epistemic regimes:
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.0em]
  \item \textbf{Provable Scotoma:} $\mathrm{Adm}_{{{sym:probe-suite}}} = \emptyset$;
  \item \textbf{Unique Conceptual Residuum:} $|{{sym:pareto-res}}(H \Rightarrow C)| = 1$ up to extent equivalence;
  \item \textbf{Multi-Dimensional Pareto Schism:} $|{{sym:pareto-res}}(H \Rightarrow C)| \ge 2$ exhibits incomparable maximal residua.
\end{enumerate}
\end{theorem}
\begin{proof}
If $\mathrm{Adm}_{{{sym:probe-suite}}} = \emptyset$, regime~(i) holds. Otherwise classical choice produces an admissible extent and well-foundedness yields a minimal element $m$ under strict deductive weakening (\texttt{WellFounded.min}), which is inclusion-maximal in $\mathrm{Adm}_{{{sym:probe-suite}}}$. Excluded middle on the existence of a non-equivalent element in {{sym:pareto-res}} separates regime~(ii) from regime~(iii), and mutual exclusivity follows directly from uniqueness.
\end{proof}

\begin{theorem}[Flow F1 Threshold Ordering]\label{ch01:thm:flow-f1-threshold-order}%
\uses{ch01:def:adm-pareto-frontier}%
For any finite-horizon decidable monotone probe filtration $\mathcal{P}_t$ over a calibrated probe suite {{sym:probe-suite}} ({{ref:ch01:def:adm-pareto-frontier}}), define {{sym:twake}}, {{sym:tdogma}} $\in \mathbb{N} \cup \{\infty\}$ as the first stage admitting an Aperture or collapsing $T$ to Dogma respectively ($\infty$ when unattained). Then constructively and unconditionally,
\[
  {{sym:twake}} \le {{sym:tdogma}}.
\]
\end{theorem}
\begin{proof}
At every stage $t$ where Dogma holds, $T$ itself is closed under the active probes and satisfies $K \subseteq T \subseteq T$, witnessing an Aperture at stage $t$. Pointwise implication between the finite-horizon Boolean indicators directly yields ${{sym:twake}} \le {{sym:tdogma}}$ in $\mathbb{N} \cup \{\infty\}$ without classical choice or propositional extensionality.
\end{proof}

