\begin{theorem}[Three-Way Model-Space Failure of Naive Pullback Along {{sym:piset}}]\label{ch02:thm:three-way-pullback-failure}%
\uses{ch02:def:gb0-model-category}%
Along a proper $\mathcal{L}_\in$-elementary or $\in$- and pair-preserving embedding $f : M_{\mathrm{fin}} \hookrightarrow M_{\mathrm{full}}$ in {{sym:mod-gb0}}, naive trace pullback $f^*\mathcal{D} := \{f^{-1}[D] \subseteq |M_{\mathrm{fin}}| \mid D \in \mathcal{D}\}$ fails to yield Cartesian lifts for {{sym:piset}} along three independent obstructions~\cite{godel1940}:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item \textbf{Subclass Separation Leak:} For $M_{\mathrm{fin}}$ supporting finite/tail-constant sets over $\mathbb{N}$ and $M_{\mathrm{full}}$ adjoining all $A \subseteq \mathbb{N}$, the definable class $\mathrm{even} \in {{sym:def-functor}}(M_{\mathrm{full}})$ pulls back onto a bounded subclass $f^{-1}[\mathrm{even}] \subseteq \omega \in M_{\mathrm{fin}}$ having no representing set in $M_{\mathrm{fin}}$.
  \item \textbf{G\"odel G4 Domain-Projection Failure:} Taking an external witness $y_0 \in M_{\mathrm{full}} \setminus \mathrm{range}(f)$ and $D := \{(f(x_0), y_0)\} \in {{sym:def-functor}}(M_{\mathrm{full}})$, we have $\mathrm{dom}^{M_{\mathrm{fin}}}(f^{-1}[D]) = \emptyset \neq \{x_0\} = f^{-1}[\mathrm{dom}^{M_{\mathrm{full}}}(D)]$.
  \item \textbf{Preimage Collapse (Non-Uniqueness):} The distinct classes $D_1 := \emptyset \neq \{y_0\} =: D_2$ in $\mathcal{D}$ satisfy $f^{-1}[D_1] = \emptyset = f^{-1}[D_2]$, blocking unique Cartesian mediating lifts.
\end{enumerate}
\end{theorem}
\begin{proof}
Construct $M_{\mathrm{fin}}$ with atom carrier $\mathbb{N}$, tail-constant finite-override sets $S$, and inductive pairs $\langle x, y \rangle$, and take $\mathcal{C}_{\mathrm{fin}}$ to be all finitely supported predicates invariant under tail atom permutations above a finite bound $N$. Then $(M_{\mathrm{fin}}, \mathcal{C}_{\mathrm{fin}}) \models {{sym:gb0}}$: closure under G\"odel operations \textbf{G1--G8} follows by transporting witness pairs under tail involutions, while Subclass Separation holds by overriding $[0, N)$ and setting the tail value at $N$. Embedding $M_{\mathrm{fin}} \hookrightarrow M_{\mathrm{full}}$ over $\mathbb{N}$ leaves $y_0 := \mathrm{even}$ outside $\mathrm{range}(f)$ and non-tail-constant above every finite override bound, giving~(1); evaluating $f^{-1}[D]$ at $y_0 \notin \mathrm{range}(f)$ yields~(2) and~(3).
\end{proof}

\begin{proposition}[Syntactic Pullback Square for Conservative Extensions vs.\ Breakdown]\label{ch02:prop:syntactic-conservative-pullback}%
\uses{ch02:thm:three-way-pullback-failure,ch02:thm:def-left-adjoint-coreflection}%
In contrast to the semantic model-space pullback failure of Theorem~\ref{ch02:thm:three-way-pullback-failure}, pass to the syntactic interpretability preorder $(\mathbf{Th}_{\mathrm{Set}}, \mathbf{Th}_{\mathrm{Cls}})$ of set and class theories~\cite{joyal_moerdijk1995} equipped with minimal expansion ${{sym:def-functor}}_{\mathrm{syn}}$ and $\mathcal{L}_\in$-trace $\mathrm{Tr}_{\mathrm{Set}}$ satisfying ${{sym:def-functor}}_{\mathrm{syn}}(T) \le S \iff T \le \mathrm{Tr}_{\mathrm{Set}}(S)$ and $\mathrm{Tr}_{\mathrm{Set}}({{sym:def-functor}}_{\mathrm{syn}}(T)) \le T$. Whenever $T_0 \le T_1$ in $\mathbf{Th}_{\mathrm{Set}}$, $E_0$ is $\mathcal{L}_\in$-conservative over $T_0$ ($\mathrm{Tr}_{\mathrm{Set}}(E_0) \equiv T_0$), and $E_1 \equiv {{sym:def-functor}}_{\mathrm{syn}}(T_1) \sqcup E_0$:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item The opcartesian pushout square satisfies the pullback universal property against all minimal class extensions ${{sym:def-functor}}_{\mathrm{syn}}(X)$ and along the set-trace square $\mathrm{Tr}_{\mathrm{Set}}(E_0) \to \mathrm{Tr}_{\mathrm{Set}}(E_1) \leftarrow T_1$.
  \item Conversely, whenever a class extension $L_0$ leaks an $\mathcal{L}_\in$-sentence $X \le \mathrm{Tr}_{\mathrm{Set}}(L_0)$ that holds in $T_1$ yet fails in $T_0$ (previewing Chapter~3 when Replacement or Foundation is dropped~\cite{felgner1971}), the pullback square collapses at ${{sym:def-functor}}_{\mathrm{syn}}(X)$.
\end{enumerate}
\end{proposition}
\begin{proof}
For~(1), if ${{sym:def-functor}}_{\mathrm{syn}}(X) \le E_0$ then by adjunction $X \le \mathrm{Tr}_{\mathrm{Set}}(E_0) \le T_0$, whence ${{sym:def-functor}}_{\mathrm{syn}}(X) \le {{sym:def-functor}}_{\mathrm{syn}}(T_0)$ by monotonicity; conversely $T_0 \le T_1$ and $\mathrm{Tr}_{\mathrm{Set}}({{sym:def-functor}}_{\mathrm{syn}}(T_0)) \le T_0 \le \mathrm{Tr}_{\mathrm{Set}}(E_0)$ yield ${{sym:def-functor}}_{\mathrm{syn}}(X) \le E_0$. Similarly, trace projection gives $\mathrm{Tr}_{\mathrm{Set}}(E_0) \times_{\mathrm{Tr}_{\mathrm{Set}}(E_1)} T_1 \equiv T_0$. Part~(2) follows contrapositively from unit and $\mathcal{L}_\in$-conservativity of ${{sym:def-functor}}_{\mathrm{syn}}(T_0)$.
\end{proof}

\begin{proposition}[Unbundling Limitation of Size Over {{sym:gb0}} and $2\times 2$ Independence]\label{ch02:prop:los-unbundling-independence}%
\uses{vol1:prop:los-smuggles-gc,ch02:def:gb0-model-category}%
Expanding Volume~I ({{ref:vol1:prop:los-smuggles-gc}}), over Replacement-free, Choice-free {{sym:gb0}}:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item Von Neumann's Limitation of Size ($\mathsf{LoS}$: a class $C$ fails to be small iff $C$ surjects onto $V$) is strictly equivalent to $(\mathrm{Rep} \wedge \mathsf{GC})$, so ${{sym:gb0}} + \mathsf{LoS} = {{sym:nbg}}$ smuggles Global Choice across Choice-free bases.
  \item Over {{sym:gb0}}, $\mathrm{Rep}$ and $\mathsf{GC}$ are mutually independent: $(\mathrm{Rep} \wedge \neg\mathsf{GC} \wedge \neg\mathsf{LoS})$ holds in tail Easton models $(M, {{sym:def-functor}}(M))$~\cite{easton1970,felgner1971}, while $(\mathsf{GC} \wedge \neg\mathrm{Rep} \wedge \neg\mathsf{LoS})$ holds in G\"odel's $(L_{\omega_\omega^L}, {{sym:def-functor}}(L_{\omega_\omega^L}))$~\cite{godel1940}.
\end{enumerate}
\end{proposition}
\begin{proof}
For $(\mathsf{LoS} \implies \mathrm{Rep} \wedge \mathsf{GC})$, Burali--Forti gives $\mathrm{Ord} \notin \mathcal{S}$, so $\mathsf{LoS}$ provides a surjection $p : \mathrm{Ord} \twoheadrightarrow V$ whose minimal-preimage selector yields $\mathsf{GC}$; for $\mathrm{Rep}$, if $F[A] \notin \mathcal{S}$ for small $A$, composing $\mathsf{LoS}$'s surjection $q : F[A] \twoheadrightarrow V$ with $F$ yields $h : A \twoheadrightarrow V$, refuting Russell--Cantor diagonalization on $D = \{a \in A \mid a \notin h(a)\}$. Conversely, under $\mathrm{Rep} + \mathsf{GC}$ Foundation stratifies $V = \bigcup_{\alpha} V_\alpha$, giving $\Phi : V \xrightarrow{\sim} \mathrm{Ord}$, and every proper class $C$ maps bijectively onto $\mathrm{Ord}$ via initial-segment order types (without $\mathsf{ETR}_{\mathrm{Ord}}$), establishing $\mathsf{LoS}$. For independence, Easton tail forcing~\cite{easton1970} yields $\mathrm{Rep} + \neg\mathsf{GC}$, whereas in $L_{\omega_\omega^L}$ G\"odel condensation~\cite{godel1940} verifies Power Set and $\mathsf{Z}$ alongside the global $<_L$-well-order ($\mathsf{GC}$), while the countable cofinal sequence $\{\omega_n^L\}_{n < \omega}$ admits no surjection onto $L_{\omega_\omega^L}$, refuting $\mathrm{Rep}$ and $\mathsf{LoS}$.
\end{proof}

\begin{theorem}[Williams's Fixed-Set Universality and Independent-Generator Fiber Embedding]\label{ch02:thm:williams-fixed-set-kaleidoscope}%
\uses{ch02:def:gb0-model-category,ch02:thm:def-left-adjoint-coreflection,ch02:claim:easton-hod-unsplit-card}%
Let $M \models \mathsf{ZFC}$ be any countable model, held completely rigid via $\mathrm{id}_M$.
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item \textbf{Fixed-Set Universality (Williams~2018~\cite{williams2018}):} The vertical fiber poset ${{sym:piset}}^{-1}(M)$ of ${{sym:gbc}}$-realizations $(M, \mathcal{C})$ ordered by class inclusion $\mathcal{C} \subseteq \mathcal{C}'$ embeds every countable partial order~\cite{felgner1971}.
  \item \textbf{Independent-Generator Order Embedding:} For any partial order $(P, \le)$ and any algebraically independent generator family $(G_p)_{p \in P}$ with monotone class closure $\mathrm{cl}$ over a fixed base $M$, the principal-ideal map $p \mapsto \mathcal{C}_{\downarrow p} := \mathrm{cl}(\{G_q \mid q \le p\})$ is a strict order embedding $(P, \le) \hookrightarrow_o {{sym:piset}}^{-1}(M)$ holding $M$ identically rigid.
\end{enumerate}
\end{theorem}
\begin{proof}
For~(2), monotonicity $p \le q \implies \mathcal{C}_{\downarrow p} \subseteq \mathcal{C}_{\downarrow q}$ is immediate from monotonicity of $\mathrm{cl}$; conversely, if $\mathcal{C}_{\downarrow p} \subseteq \mathcal{C}_{\downarrow q}$ then $G_p \in \mathcal{C}_{\downarrow q}$, and algebraic independence forces $p \le q$, while antisymmetry yields injectivity. To realize~(1) over countable $M \models \mathsf{ZFC}$, Williams~\cite[Ch.~2--3]{williams2018} constructs by product class forcing a countable mutually generic family of proper classes $(G_p)_{p \in P}$ preserving ${{sym:gbc}}$ and remaining independent under class-definable combinations.
\end{proof}

