\begin{theorem}[Choiceless Saturated Anafunctoriality vs.\ Functorial Global Choice Splitting]\label{ch03:thm:anafunctor-vs-functorial-gc-splitting}%
\uses{vol1:prop:large-equiv-splitting,ch02:claim:easton-hod-unsplit-card}%
Let $\mathrm{skel} : \mathcal{S} \to C$ be an equipollence groupoid projection onto a skeletal base $C$ (such as $\mathrm{skel}(X) = |X| \in {{sym:card-cat}}$ over {{sym:gbc}} in Proposition~\ref{vol1:prop:large-equiv-splitting} and Claim~\ref{ch02:claim:easton-hod-unsplit-card}) equipped with internal groupoid equivalences $\mathrm{Eqv}(s_1, s_2)$ satisfying $\mathrm{skel}(s_1) = \mathrm{skel}(s_2) \iff \exists e : \mathrm{Eqv}(s_1, s_2)$ and surjectivity onto $C$~\cite{makkai1996}. Then:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item \textbf{Choiceless Saturated Anafunctoriality:} The relational anafunctor inverse span $R(c, s) := (\mathrm{skel}(s) = c)$ is unconditionally total, equipollence-saturated, single-orbit fiber-transitive, and base-coherent with zero choice axioms---explaining why anafunctorial large category theory operates entirely within {{sym:gbc}}.
  \item \textbf{Bi-Definability of Functorial Splitting and Global Choice:} Constructing a functorial section $\mathrm{sec} : C \to \mathcal{S}$ paired with coherent transport equivalences $\eta_s : \mathrm{Eqv}(\mathrm{sec}(\mathrm{skel}(s)), s)$ and functorial morphism transport is constructively equivalent to a uniform Global Choice selector $(\mathrm{pickObj}, \mathrm{pickEqv})$ across all $\mathrm{skel}$-fibers (climbing to {{sym:nbg}}~\cite{felgner1971}).
  \item \textbf{Vertical Gauge Torsor Uniqueness:} Any two functorial splittings $F_1, F_2$ differ by a unique vertical gauge torsor $(g_c, v_s)$ of section transitions and fiberwise automorphisms $v_s \in \mathrm{Aut}(s)$ satisfying $g_{\mathrm{skel}(s)} \cdot \eta^{(2)}_s = \eta^{(1)}_s \cdot v_s$.
\end{enumerate}
\end{theorem}
\begin{proof}
For~(1), totality is $\mathrm{skel\_surj}$, saturation and fiber transitivity follow directly from $\mathrm{skel}(s_1) = \mathrm{skel}(s_2) \iff \mathrm{Nonempty}(\mathrm{Eqv}(s_1, s_2))$, and base coherence is transitivity of equality. For~(2), a functorial splitting $(F.\mathrm{sec}, F.\eta)$ yields $\mathrm{pickObj}(c) := F.\mathrm{sec}(c)$ and $\mathrm{pickEqv}(s_1, s_2) := (F.\eta_{s_1})^{-1} \cdot F.\eta_{s_2}$ across matching fibers; conversely, $(\mathrm{pickObj}, \mathrm{pickEqv})$ defines $\eta_s := \mathrm{pickEqv}(\mathrm{sec}(\mathrm{skel}(s)), s)$ and conjugates groupoid arrows via $\mathrm{map}(f) := \eta_{s_1} \cdot f \cdot \eta_{s_2}^{-1}$, where groupoid associativity and unit laws immediately verify functoriality and naturality without any choice axiom. For~(3), setting $g_c := F_1.\eta_{F_2.\mathrm{sec}(c)}$ and $v_s := (F_1.\eta_s)^{-1} \cdot g_{\mathrm{skel}(s)} \cdot F_2.\eta_s$ solves $g_{\mathrm{skel}(s)} \cdot F_2.\eta_s = F_1.\eta_s \cdot v_s$, and left-cancellation by $F_1.\eta_s$ proves uniqueness of $v_s$ (which collapses to a free simply transitive torsor whenever $F_1.\mathrm{sec} = F_2.\mathrm{sec}$).
\end{proof}

\begin{proposition}[Equipollence Quotient Stratum Calibration on $\mathrm{Type}\,u$]\label{ch03:prop:skeleton-quotient-choice-stratum}%
\uses{vol1:prop:large-equiv-splitting,ch03:thm:anafunctor-vs-functorial-gc-splitting}%
Let $\mathrm{EquipollenceQuot} := \mathrm{Type}\,u / {\approx}$ be the Lean~4 quotient by equipollence $\alpha \approx \beta \iff \mathrm{Nonempty}(\alpha \simeq \beta)$. Then:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item \textbf{Amber Quotient Stratum:} The canonical projection $\mathrm{equipollenceClass} : \mathrm{Type}\,u \to \mathrm{EquipollenceQuot}$ satisfies $\mathrm{equipollenceClass}(\alpha) = \mathrm{equipollenceClass}(\beta) \iff \mathrm{Nonempty}(\alpha \simeq \beta)$ and surjectivity $\forall q,\,\exists\alpha,\,[\alpha]=q$ purely in the \textbf{Amber} stratum (\texttt{[propext, Quot.sound]}, zero choice axioms)~\cite{makkai1996}.
  \item \textbf{Crimson Representative Splitting:} Extracting a global representative map $\mathrm{rep} : \mathrm{EquipollenceQuot} \to \mathrm{Type}\,u$ with $\forall q,\,\mathrm{equipollenceClass}(\mathrm{rep}(q)) = q$ and uniform equivalences $\alpha \simeq \mathrm{rep}([\alpha])$ (via \texttt{Quotient.out}) strictly crosses into the \textbf{Crimson} stratum (\texttt{[propext, Classical.choice, Quot.sound]}), directly calibrating the universe-level Choice collapse analyzed in Chapter~9 (Obstruction~2b).
\end{enumerate}
\end{proposition}
\begin{proof}
Part~(1) uses \texttt{Quotient.eq} and \texttt{Quotient.ind} without invoking choice. Part~(2) applies \texttt{Quotient.out} and \texttt{Quotient.out\_eq} to construct the global section $\mathrm{rep}$, then applies \texttt{Classical.choice} pointwise to extract coherent transport equivalences $\alpha \simeq \mathrm{rep}([\alpha])$ across every fiber.
\end{proof}

\begin{theorem}[Felgner's $\kappa$-Closed Forcing Membrane and {{sym:nbg}} Conservativity]\label{ch03:thm:felgner-kappa-closed-membrane}%
\uses{vol1:prop:large-equiv-splitting,ch02:def:gb0-model-category}%
Over $\mathsf{ZFC}$, von Neumann--Bernays--G\"odel class theory {{sym:nbg}} ($= {{sym:gbc}} + \mathsf{GC}$) is syntactically $\mathcal{L}_\in$-conservative over $\mathsf{ZFC}$~\cite[Thm.~1, pp.~45--56]{felgner1971}. Isolating the two load-bearing set axioms inside Felgner's class forcing $\mathbb{P}$ of set-sized injective partial functions $p : \alpha \hookrightarrow V$ ordered by reverse inclusion:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item \textbf{Foundation Insulation:} Stratifying $V = \bigcup_{\alpha \in \mathrm{Ord}} V_\alpha$ guarantees that Easton-style rank stages cover every set $x \in V$ via dense extension sets $D_x := \{p \in \mathbb{P} \mid x \in \mathrm{ran}(p)\}$~\cite{easton1970}.
  \item \textbf{Replacement Membrane ($<\kappa$-Distributivity):} For every cardinal $\kappa$, Replacement compresses any $\kappa$-indexed family of dense open conditions $\langle D_\xi \rangle_{\xi < \kappa}$ into a single master condition $q \le p$ inside $\bigcap_{\xi < \kappa} D_\xi$, ensuring zero new bounded subsets of any ground set $A$ and preserving all first-order $\mathcal{L}_\in$-truth.
\end{enumerate}
\end{theorem}
\begin{proof}
Let $\varphi$ be a first-order $\mathcal{L}_\in$-sentence such that $\mathsf{NBG} \vdash \varphi$, and assume for contradiction that $\mathsf{ZFC} + \neg\varphi$ has a countable transitive model $M$ (via Reflection and L\"owenheim--Skolem for the finite fragment used in the proof). Work in $(M, \mathrm{Def}(M)) \models {{sym:gbc}}$. Define the Easton-style class forcing poset $\mathbb{P} \in \mathrm{Def}(M)$ whose conditions are set-sized well-orderings $p \in M$ (specifically injective maps $p : \alpha \hookrightarrow M$ for $\alpha \in \mathrm{Ord}^M$) ordered by reverse inclusion $q \le p \iff q \supseteq p$. Under Foundation in $M$, $M = \bigcup_{\alpha \in \mathrm{Ord}^M} V_\alpha^M$, so for each $x \in M$ the dense class $D_x := \{p \in \mathbb{P} \mid x \in \mathrm{ran}(p)\}$ meets every condition (extending $p$ by placing $x$ at $\mathrm{dom}(p)$ if $x \notin \mathrm{ran}(p)$). Crucially, for any regular cardinal $\kappa \in \mathrm{Ord}^M$ and any $p \in \mathbb{P}$, any set-sized sequence $\langle \Delta_\xi \rangle_{\xi < \kappa}$ of dense open subclasses of $\mathbb{P}$ admits a descending chain $p = p_0 \supseteq p_1 \supseteq \cdots \supseteq p_\xi \supseteq \cdots$ ($\xi < \kappa$) defined inside $M$ via Replacement and $\mathrm{AC}$, whose union $q := \bigcup_{\xi < \kappa} p_\xi$ belongs to $M$ (by Replacement) and forces every $x \in A$ for $|A| < \kappa$; hence $\mathbb{P}$ is $<\kappa$-distributive for every cardinal $\kappa$ of $M$. By transfinite rank induction over $V_\alpha^M$ (and the fact that $\mathbb{P}$ is definable over $M$), adjoining a generic class well-ordering $G \subseteq \mathbb{P}$ adds zero new sets to $M$, so $(M, \mathcal{C}[G]) \models {{sym:nbg}}$ preserves all first-order $\mathcal{L}_\in$-sentences of $M$, yielding $(M, \mathcal{C}[G]) \models \neg\varphi$---contradicting $\mathsf{NBG} \vdash \varphi$. In \texttt{ForcingMembrane.lean}, \texttt{felgner\_kappa\_closed\_membrane} mechanizes the abstract implication $\mathrm{RankExhaustive} \wedge \mathrm{SmallDenseIntersectionClosed} \implies \mathrm{ZeroBoundedSubsetLeak}$ and its concrete witness \texttt{natRankMembrane} axiom-free.
\end{proof}

\begin{proposition}[Hartogs--Scott Prewellordering Stages and Glazer's Surjection Over {{sym:gbc0}} + $\mathsf{GC}$]\label{ch03:prop:glazer-hartogs-scott-surjection}%
\uses{vol1:thm:glazer-nonconservativity,ch02:def:gb0-model-category}%
Work over Replacement-free {{sym:gb0}} (and {{sym:gbc0}}) augmented with Global Choice $\mathsf{GC}$, requiring neither Class Replacement nor von Neumann ordinals above $\omega + \omega$:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item \textbf{Hartogs--Scott Prewellordering Stage:} For any small set $A \in \mathcal{S}$, let $\mathrm{WO}(A) \subseteq \mathcal{P}(A \times A)$ be the small set of well-orderings of subsets of $A$, and let $W^+(A) := \mathrm{WO}(A)/{\cong} \subseteq \mathcal{P}^2(A \times A)$ be its canonical Hartogs--Scott quotient stage of order types. Global Choice induces an injective section $W^+(A) \hookrightarrow \mathrm{WO}(A)$ splitting the small-domain surjection $\mathrm{WO}(A) \twoheadrightarrow W^+(A)$.
  \item \textbf{Glazer's Small-Domain Compression:} Given the class witness $\psi_{\mathrm{fnd}}$ of Volume~I (Theorem~\ref{vol1:thm:glazer-nonconservativity}, comprising an $\omega$-indexed sequence $\langle X_n \rangle_{n < \omega}$ of nonempty countable sets, a class $A$ separated by $R \subseteq (\bigcup_{n<\omega} X_n) \times A$, and a class surjection $P_2 : A \twoheadrightarrow W_2$ onto $W_2 \in \mathcal{P}^5(\omega)$ of order type $\omega_2$)~\cite{glazer2023}, $\mathsf{GC}$ selects uniform enumerations $f_n : \omega \twoheadrightarrow X_n$ for all $n < \omega$, injecting $A$ into $\mathcal{P}(\omega \times \omega)$ so that \textbf{G4} domain projection and Subclass Separation carve out a small partial surjection $\mathcal{P}(\omega \times \omega) \rightharpoonup W_2$ (hence $\mathcal{P}(\omega) \twoheadrightarrow W_2$), refuting $\mathsf{CH}$ and $\theta_{\mathrm{Glz}}$.
\end{enumerate}
\end{proposition}
\begin{proof}
For~(1), because $\mathrm{WO}(A)$ is a small set of well-orderings closed under isomorphism equivalence classes inside $\mathcal{P}(A \times A)$, the quotient $W^+(A) := \mathrm{WO}(A)/{\cong}$ embeds into $\mathcal{P}^2(A \times A)$ via Scott's equivalence classes without invoking Replacement; $\mathsf{GC}$ applied to the small equivalence classes picks one representative $s(w) \in \mathrm{WO}(A)$ per $w \in W^+(A)$, yielding an injective right inverse $s : W^+(A) \hookrightarrow \mathrm{WO}(A)$. For~(2), over {{sym:gbc0}} + $\mathsf{GC}$ (where $W_2 \subseteq W^+(W^+(\omega))$ sits cleanly inside $\mathcal{P}^5(\omega)$ without requiring $\omega_2 \in \mathrm{Ord}$), $\mathsf{GC}$ simultaneously chooses surjections $f_n : \omega \twoheadrightarrow X_n$ from the nonempty sets of enumerations $\{\mathrm{Surj}(\omega, X_n)\}_{n < \omega}$. Defining the class code $\mathrm{code}(a) := \{(m, n) \in \omega \times \omega \mid f_n(m) \mathrel{R} a\} \in \mathcal{P}(\omega \times \omega)$ makes $a \mapsto \mathrm{code}(a)$ injective because $R$ separates points of $A$ and every $x \in X_n$ lies in $\mathrm{ran}(f_n)$. By \textbf{G1--G8} (Definition~\ref{ch02:def:gb0-model-category}), the class relation
\[
  \Phi := \{(S, w) \in \mathcal{P}(\omega \times \omega) \times W_2 \mid \exists a \in A\,(S = \mathrm{code}(a) \wedge P_2(a) = w)\}
\]
is formed by \textbf{G4} domain projection over the unbounded existential quantifier $a \in A$; since $\Phi \subseteq \mathcal{P}(\omega \times \omega) \times W_2 \in \mathcal{S}$, Subclass Separation forces $\Phi$ to be a small set, and injectivity of $\mathrm{code}$ makes $\Phi$ single-valued and surjective onto $W_2$. Transporting along $\omega \times \omega \cong \omega$ yields a small surjection $\mathcal{P}(\omega) \twoheadrightarrow W_2$, refuting $\mathsf{CH}$ and therefore proving ${{sym:gbc0}} + \mathsf{GC} \vdash \neg\theta_{\mathrm{Glz}}$.
\end{proof}

\begin{theorem}[Lindenbaum--Stone Transgression Operator {{sym:dset}} and Pullback Exactness]\label{ch03:thm:piset-transgression-exactness}%
\uses{vol1:thm:quantitative-conservation,ch02:prop:syntactic-conservative-pullback}%
Let $\mathrm{Sys} = (\mathbf{Th}_{\mathrm{Set}}, \mathbf{Th}_{\mathrm{Cls}}, {{sym:def-functor}}_{\mathrm{syn}} \dashv \mathrm{Tr}_{\mathrm{Set}})$ be a syntactic base--class system as in Proposition~\ref{ch02:prop:syntactic-conservative-pullback} (satisfying $\mathrm{Tr}_{\mathrm{Set}}({{sym:def-functor}}_{\mathrm{syn}}(T)) \le T$). Mirroring the quantitative Giraud--Leray transgression $d_2$ of Volume~I (Theorem~\ref{vol1:thm:quantitative-conservation})~\cite{giraud1971}, define for any base set theory $T_{\mathrm{base}}$ and class extension $\tau \in \mathbf{Th}_{\mathrm{Cls}}$ the \textbf{Horizontal Leakage / Transgression Operator}
\[
  {{sym:dset}}(T_{\mathrm{base}}, \tau) \;:=\; \mathrm{Tr}_{\mathrm{Set}}\bigl({{sym:def-functor}}_{\mathrm{syn}}(T_{\mathrm{base}}) \sqcup \tau\bigr)
\]
together with its open leakage locus ${{sym:uleak}}(T_{\mathrm{base}}, \tau) := \{X \le {{sym:dset}}(T_{\mathrm{base}}, \tau) \mid X \not\le T_{\mathrm{base}}\}$ in the Lindenbaum/Stone frame of $T_{\mathrm{base}}$ (writing ${{sym:dset}}(T_{\mathrm{base}}, \tau) = \bot_{T_{\mathrm{base}}}$ when $\forall X \le {{sym:dset}}(T_{\mathrm{base}}, \tau),\; X \le T_{\mathrm{base}}$). Then:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item \textbf{Exactness Criterion:} ${{sym:def-functor}}_{\mathrm{syn}}(T_{\mathrm{base}}) \sqcup \tau$ is $\mathcal{L}_\in$-conservative over $T_{\mathrm{base}}$ if and only if ${{sym:dset}}(T_{\mathrm{base}}, \tau) = \bot_{T_{\mathrm{base}}}$ (equivalently, ${{sym:uleak}}(T_{\mathrm{base}}, \tau) = \emptyset$).
  \item \textbf{Pullback Cartesianness Equivalence:} ${{sym:dset}}(T_0, \tau) = \bot_{T_0}$ if and only if for every extension $T_0 \le T_1$, the opcartesian square connecting ${{sym:def-functor}}_{\mathrm{syn}}(T_0)$, ${{sym:def-functor}}_{\mathrm{syn}}(T_1)$, ${{sym:def-functor}}_{\mathrm{syn}}(T_0) \sqcup \tau$, and ${{sym:def-functor}}_{\mathrm{syn}}(T_1) \sqcup \tau$ is a genuine pullback against minimal expansions ${{sym:def-functor}}_{\mathrm{syn}}(X)$.
  \item \textbf{Base-Strengthening Absorption:} Whenever $T_0 \le T_1$ absorbs ${{sym:dset}}(T_0, \tau) \le T_1$ (for instance, adjoining Replacement and Foundation over $\mathsf{ZC}_{\neg\mathrm{Reg}}$~\cite{felgner1971}), every open leak $X \in {{sym:uleak}}(T_0, \tau)$ is absorbed into $T_1$; if moreover $T_1$ is trace-absorption-stable (${{sym:dset}}(T_1, \tau) \le T_1 \sqcup {{sym:dset}}(T_0, \tau)$), then ${{sym:dset}}(T_1, \tau) = \bot_{T_1}$ and ${{sym:uleak}}(T_1, \tau) = \emptyset$.
\end{enumerate}
\end{theorem}
\begin{proof}
By the syntactic adjunction ${{sym:def-functor}}_{\mathrm{syn}}(T) \le {{sym:def-functor}}_{\mathrm{syn}}(T) \sqcup \tau$, we unconditionally have $T \le {{sym:dset}}(T, \tau)$; hence $\mathrm{Tr}_{\mathrm{Set}}({{sym:def-functor}}_{\mathrm{syn}}(T) \sqcup \tau) \equiv T \iff {{sym:dset}}(T, \tau) \le T \iff {{sym:dset}}(T, \tau) = \bot_T$, proving~(1). For~(2), if ${{sym:dset}}(T_0, \tau) = \bot_{T_0}$, then $E_0 := {{sym:def-functor}}_{\mathrm{syn}}(T_0) \sqcup \tau$ is $\mathcal{L}_\in$-conservative over $T_0$, so Proposition~\ref{ch02:prop:syntactic-conservative-pullback}(1) guarantees the pullback universal property along every $T_0 \le T_1$. Conversely, testing the pullback property at $T_1 := {{sym:dset}}(T_0, \tau) \ge T_0$ and $X := {{sym:dset}}(T_0, \tau)$ gives ${{sym:def-functor}}_{\mathrm{syn}}(X) \le {{sym:def-functor}}_{\mathrm{syn}}(T_0)$, whence adjunction and $\mathcal{L}_\in$-conservativity of ${{sym:def-functor}}_{\mathrm{syn}}(T_0)$ force $X \le T_0$, i.e.\ ${{sym:dset}}(T_0, \tau) = \bot_{T_0}$. Part~(3) follows immediately from transitivity and the join universal property on $T_1 \sqcup {{sym:dset}}(T_0, \tau) \le T_1$.
\end{proof}

