\begin{definition}[Volume~I Grounding Contract: Predicative Class--Set Ambient $(\mathcal{C}, \mathcal{S})$]\label{vol1:def:small-map-ambient}%
Pinned read-only to Volume~I (\texttt{def:small-map-ambient}, \texttt{docs/ch07\_sets\_residuum.tex:191}, Zenodo DOI \texttt{10.5281/zenodo.24238086})~\cite[\S I.1]{joyal_moerdijk1995}. A baseline predicative class--set ambient $(\mathcal{C}, \mathcal{S})$ pairs a regular category $\mathcal{C}$ of classes with a stable subcategory $\mathcal{S} \subseteq \mathcal{C}$ of small maps closed under composition, arbitrary pullbacks, diagonals, and finite disjoint sums---without quotient or regular-image descent. Under Powerclass Axiom (P1), $\mathcal{P}_{\mathcal{S}} : \mathcal{C}^{\mathrm{op}} \to \mathcal{C}$ acts contravariantly via $f \mapsto f^*$.
\end{definition}

\begin{definition}[Volume~I Grounding Contract: Axis~VI Quotient-Image Descent]\label{vol1:def:axis-vi-replacement}%
Pinned read-only to Volume~I (\texttt{def:axis-vi-replacement}, \texttt{docs/ch07\_sets\_residuum.tex:228}, Zenodo DOI \texttt{10.5281/zenodo.24238086})~\cite[\S\S 1--3]{joyal_moerdijk1995}. Over $(\mathcal{C}, \mathcal{S})$, \textbf{Axis~VI} asserts small-image descent $\kappa_{\mathrm{Rep}} : \mathrm{im}(f) \in \mathcal{S}$ for every morphism $f : I \to C$ with $I \in \mathcal{S}$, equivalently promoting $\mathcal{P}_{\mathcal{S}}$ to a covariant endofunctor via direct image $\exists_g$ and compressing small-indexed colimits under Small Union.
\end{definition}

\begin{proposition}[Volume~I Grounding Contract: Countable Colimit Escape in $V_{\omega+\omega}$]\label{vol1:prop:etcs-colimit-escape}%
Pinned read-only to Volume~I (\texttt{prop:etcs-colimit-escape}, \texttt{docs/ch07\_sets\_residuum.tex:173}, Zenodo DOI \texttt{10.5281/zenodo.24238086})~\cite{joyal_moerdijk1995,mathias2001}. Over $V_{\omega+\omega} \models \mathsf{ZC}$ (and $\mathsf{ETCS} \simeq \mathsf{Mac}$), each finite iterate $\mathcal{P}^n(\mathbb{N})$ is small, yet its countable colimit escapes $\mathcal{S}$ with strict inclusion $\bigcup_{n \in \mathbb{N}} \mathcal{P}^n(\mathbb{N}) \subsetneq V_{\omega+\omega} = \bigcup_{n \in \mathbb{N}} \mathcal{P}^n(V_\omega)$ (Guardrail~5).
