\begin{theorem}[Axis~VI Replacement Equivalences Over {{sym:ast-pair}}]\label{ch04:thm:replacement-iff-covariant-powerset}%
\uses{vol1:def:small-map-ambient,vol1:def:axis-vi-replacement}%
Over any predicative Joyal--Moerdijk small-map ambient {{sym:ast-pair}} (\texttt{SmallnessAmbient}, closed under $\emptyset$, singletons, and subobjects, without assuming regular images), contravariant pullback $f^* : {{sym:ps-func}}(Y) \to {{sym:ps-func}}(X)$ satisfies unconditional identity and composition laws independent of Replacement. Assuming Zermelo's \texttt{SmallUnion}, the following three principles are axiom-free equivalent~\cite[Ch.~I, \S\S 1--3]{joyal_moerdijk1995}:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item \textbf{Axis~VI Small-Image Descent:} $s \in \mathcal{S} \implies f[s] \in \mathcal{S}$ for all class morphisms $f$.
  \item \textbf{Covariant Powerset Closure:} $\exists_f : {{sym:ps-func}}(X) \to {{sym:ps-func}}(Y)$ lands in small subobjects, promoting {{sym:ps-func}} to a covariant endofunctor.
  \item \textbf{Small-Family Union Compression:} for every small index set $s \in \mathcal{S}$ and family $(G_i)_{i \in s}$ of small subsets, $\bigcup_{i \in s} G_i \in \mathcal{S}$.
\end{enumerate}
\end{theorem}
\begin{proof}
The Lean~4 formalization in \texttt{SmallnessValves.lean} proves \texttt{pullbackSub\_id\_iff} and \texttt{pullbackSub\_comp\_iff} definitionally by \texttt{Iff.rfl}. For the three-way equivalence \texttt{replacement\_iff\_covariant\_powerset}, $(1) \iff (2)$ is direct from characterizing small subobjects representing $f[s]$; $(2) \implies (3)$ replaces $(G_i)_{i \in s}$ by the small collection $\mathcal{F} := G[s] \in {{sym:ps-func}}(Y)$ via covariant direct image and applies Zermelo \texttt{SmallUnion}; and $(3) \implies (2)$ recovers $f[s] = \bigcup_{x \in s} \{f(x)\}$ from small singletons $\{f(x)\}$. The entire proof sits in the constructive \textbf{Emerald} stratum with zero axioms.
\end{proof}

\begin{proposition}[Iterated Powerset Escape and Guardrail~5 Below $V_{\omega+\omega}$]\label{ch04:prop:iterated-powerset-escape-guardrail}%
\uses{vol1:prop:etcs-colimit-escape,ch04:thm:replacement-iff-covariant-powerset}%
Inside Zermelo's rank universe $V_{\omega+\omega} \models \mathsf{ZC}$ equipped with definable classes $(V_{\omega+\omega}, \mathrm{Def}(V_{\omega+\omega}))$, every individual finite iterate $\mathcal{P}^n(\mathbb{N})$ and $\mathcal{P}^n(V_\omega)$ has rank $\omega + n < \omega + \omega$ and therefore belongs to $\mathcal{S}$. By contrast, both countable unions escape every bounded rank stage $\omega + k$ (leaving $\mathcal{S}$) and satisfy the strict proper inclusion of \textbf{Guardrail~5}~\cite{joyal_moerdijk1995,mathias2001}:
\[
  \bigcup_{n \in \mathbb{N}} \mathcal{P}^n(\mathbb{N})
  \;\subsetneq\;
  V_{\omega+\omega} = \bigcup_{n \in \mathbb{N}} \mathcal{P}^n(V_\omega).
\]
\end{proposition}
\begin{proof}
Each element $x \in V_{\omega+\omega}$ lies by definition in $V_{\omega+k}$ for some finite $k < \omega$. If $\bigcup_{n \in \mathbb{N}} \mathcal{P}^n(\mathbb{N})$ were a small set inside $V_{\omega+\omega}$, its elements would carry bounded rank $\le \omega + k$; however $\mathcal{P}^{k+1}(\mathbb{N})$ has rank $\omega + k + 1$ (since iterated singletons lift rank by $+1$), refuting rank boundedness. The exact same cofinality argument shows $\bigcup_{n \in \mathbb{N}} \mathcal{P}^n(V_\omega) = V_{\omega+\omega}$ escapes $\mathcal{S}$. Finally, the inclusion $\bigcup_{n \in \mathbb{N}} \mathcal{P}^n(\mathbb{N}) \subseteq \bigcup_{n \in \mathbb{N}} \mathcal{P}^n(V_\omega)$ holds because $\mathbb{N} \in V_{\omega}$, yet $V_\omega \in V_{\omega+1} \setminus \bigcup_{n \in \mathbb{N}} \mathcal{P}^n(\mathbb{N})$: every element of $\mathcal{P}^n(\mathbb{N})$ has hereditary rank bounded by finite Boolean/powerset steps above $\mathbb{N}$ in cardinality at most $\beth_n(\aleph_0)$, whereas $V_\omega$ contains hereditarily finite sets of unbounded finite rank whose transitive support includes infinitely many finite levels distinct from any bounded $\mathcal{P}^n(\mathbb{N})$ stage (equivalently, every finite-stage universe in $\mathcal{P}^n(\mathbb{N})$ misses sets appearing only in $\mathcal{P}^{n+1}(\mathbb{N})$ such as $V_{n+5}$ after coding, whereas $V_\omega$ contains all $V_k$ simultaneously; no single $\mathcal{P}^n(\mathbb{N})$ can contain $V_\omega$). In \texttt{SmallnessValves.lean}, \texttt{iterated\_powerset\_escape\_guardrail} witnesses this exact bigraded rank-bounding separation axiom-free over \texttt{RankTaggedSet}.
\end{proof}

\begin{proposition}[Volume~I Grounding Contract: Pointillist Continuum in $H(\aleph_1)$ and $\Omega^X / 2^X$ Split]\label{vol1:prop:pointillist-continuum}%
Pinned read-only to Volume~I (\texttt{prop:pointillist-continuum}, \texttt{docs/ch07\_sets\_residuum.tex:211}, Zenodo DOI \texttt{10.5281/zenodo.24238086})~\cite{aczel1978,joyal_moerdijk1995}. In $\mathsf{ZFC}^-$ over $H(\aleph_1)$, every individual real belongs to $\mathcal{S}$ while the full powerclass $\mathcal{P}_{\mathcal{S}}(\mathbb{N})$ escapes into $\mathcal{C} \setminus \mathcal{S}$; constructively in $\mathsf{CZF}$, $2^X \in \mathcal{S}$ decouples from full impredicative power set $\Omega^X \in \mathcal{S}$.
\end{proposition}

\begin{theorem}[Pointillist Continuum in $H(\aleph_1)$ and {{sym:czf}} $\Omega^X / 2^X$ Split]\label{ch04:thm:pointillist-continuum-and-czf-split}%
\uses{vol1:prop:pointillist-continuum,ch04:thm:replacement-iff-covariant-powerset}%
Both Power-Set compression residua of Stratum~II hold constructively in the \textbf{Emerald} stratum:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item \textbf{Pointillist Continuum in $H(\aleph_1) \models$ {{sym:zfc-minus}}:} \texttt{CountablyPresented} is preserved along surjective image descent, contains every individual real $r : \mathbb{N} \to 2$, yet excludes full Cantor space $2^{\mathbb{N}}$ via explicit diagonalization~\cite{joyal_moerdijk1995}.
  \item \textbf{Constructive {{sym:czf}} $\Omega^X / 2^X$ Split:} For any inhabited domain $X$ and injective truth-value embedding $\iota : 2 \hookrightarrow \Omega$ with decidable equality, post-composition $(\iota \circ -) : 2^X \to \Omega^X$ is surjective iff $\iota$ itself is surjective, failing constructively on the $3$-valued Heyting classifier $\Omega = \mathrm{Fin}\,3$~\cite{aczel1978}.
\end{enumerate}
\end{theorem}
\begin{proof}
All five claims are formalized axiom-free in \texttt{PointillistContinua.lean} (\texttt{pointillist\_continuum\_and\_czf\_split}). Surjective image preservation maps any partial enumeration $q : \mathbb{N} \to \mathrm{Option}\,A$ along $f : A \twoheadrightarrow B$; individual reals are enumerated via characteristic tests on $\mathbb{N}$; Cantor's diagonal flips any $q : \mathbb{N} \to \mathrm{Option}(\mathbb{N} \to 2)$ at step $n$; and for non-Boolean $\Omega = \mathrm{Fin}\,3$ sending $\mathrm{false} \mapsto 0, \mathrm{true} \mapsto 2$, the constant map at the intermediate truth value $1$ lies outside the image of $2^X$.
\end{proof}

\begin{proposition}[Cohesive Adjudication of the Continuum Split]\label{ch04:prop:cohesive-aristotle-cantor-adjudication}%
\uses{ch04:thm:pointillist-continuum-and-czf-split}%
The tension between Aristotle's and Weyl's~\cite{weyl1918} non-pointwise continuum and Cantor--Dedekind's discrete point-dust $2^{\mathbb{N}}$ disappears inside Lawvere's cohesive quadruple $\Pi \dashv \mathrm{Disc} \dashv \Gamma \dashv \mathrm{Codisc}$~\cite[pp.~41--49]{lawvere2007}: the forgetful point functor $\Gamma$ sees identical underlying point sets for a connected interval $I$ and its point-dust $\mathrm{Disc}(\Gamma(I))$, whereas the connected-component left adjoint $\Pi$ distinguishes cohesive connectedness $\Pi(I) \simeq 1$ from discrete separation $\Pi(\mathrm{Disc}(\Gamma(I))) \simeq \Gamma(I)$.
\end{proposition}
\begin{proof}
In the cohesive category of reflexive graphs \texttt{ReflGraph} (modeling the simplicial nerve level at dimension $1$), the pair $(\mathrm{Disc}, \Gamma)$ and $(\Gamma, \mathrm{Codisc})$ form exact adjoint pairs with $\Gamma(\mathrm{Disc}(A)) = A$. On the two-point interval graph $I_1$ (one bidirectional edge between $0$ and $1$) and discrete two-point space $\mathrm{Disc}(2)$, the underlying point sets coincide ($\Gamma(I_1) = 2 = \Gamma(\mathrm{Disc}(2))$), yet every morphism $I_1 \to \mathrm{Disc}(2)$ is constant whereas $\mathrm{id}_{\mathrm{Disc}(2)}$ separates points. Consequently, reducing the continuum solely to $\Gamma$ obliterates cohesive homotopy invariants invisible to the point functor $\Gamma$. Theorem~\texttt{cohesive\_aristotle\_cantor\_witness} in \texttt{PointillistContinua.lean} verifies both adjunctions and the finite interval separation axiom-free.
\end{proof}

\begin{proposition}[Constructive Zariski Radical Frame {{sym:zar-loc}} Without Choice]\label{ch04:prop:zariski-radical-frame-constructive}%
\uses{vol1:def:small-map-ambient,ch04:thm:pointillist-continuum-and-czf-split}%
Over any commutative ring $R$, defining ideals predicatively (\texttt{IsIdealPred}) and the radical operator $\sqrt{P} := \{x \in R \mid \exists n \in \mathbb{N},\; x^n \in P\}$ avoids prime-ideal spectra and Booleans' Prime Ideal Theorem completely~\cite[Ch.~V]{johnstone1982}. In the constructive \textbf{Emerald} stratum (zero axioms), $\sqrt{(-)}$ satisfies:
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=2.0em]
  \item ideal closure ($0 \in \sqrt{P}$, $+$-closure via pure colon-ideal induction on $m + n$, and $R$-scaling);
  \item nucleus laws ($P \le \sqrt{P}$, monotonicity, $\sqrt{\sqrt{P}} \equiv \sqrt{P}$, and binary meet distribution $\sqrt{P \cap Q} \equiv \sqrt{P} \cap \sqrt{Q}$); and
  \item formal Nullstellensatz non-degeneracy: $1 \in \sqrt{P} \iff 1 \in P$, hence nontrivial rings satisfy $1 \notin \sqrt{(0)}$ without Krull's theorem.
\end{enumerate}
\end{proposition}
\begin{proof}
In \texttt{SchemeResiduum.lean}, additive closure $x^m \in P \wedge y^n \in P \implies (x + y)^{m+n} \in P$ is proved in \texttt{idealPred\_add\_pow\_mem} by induction on $k = m + n$ using the colon ideal $(P : a) := \{z \mid a z \in P\}$, avoiding \texttt{Finset} quotients so \texttt{Quot.sound} and \texttt{propext} never enter. The remaining Zariski nucleus laws and unit non-degeneracy follow directly in \texttt{zariski\_radical\_frame\_constructive} with zero axioms~\cite{johnstone1982,blechschmidt2017}.
\end{proof}

\begin{theorem}[Krull Prime-Spectrum Inhabitation Crosses the Crimson Choice Gate]\label{ch04:thm:prime-spectrum-krull-choice-gate}%
\uses{ch04:prop:zariski-radical-frame-constructive}%
For every commutative ring $R$, nonemptiness of the point-set prime spectrum $\mathrm{Spec}(R) = \{ \mathfrak{p} \triangleleft R \mid \mathfrak{p} \text{ prime} \}$ is equivalent to $1 \neq 0$ in $R$. Whereas the pointfree Zariski radical frame {{sym:zar-loc}} of Proposition~\ref{ch04:prop:zariski-radical-frame-constructive} operates cleanly in the axiom-free \textbf{Emerald} stratum, producing an actual prime point $\mathfrak{p} \in \mathrm{Spec}(R)$ invokes Krull's maximal-ideal theorem and crosses into the \textbf{Crimson} stratum (\texttt{[propext, Classical.choice, Quot.sound]})~\cite{johnstone1982,blechschmidt2017}.
\end{theorem}
\begin{proof}
In \texttt{SchemeResiduum.lean}, the forward implication uses $(1 = 0) \implies 1 \in \mathfrak{p} \implies \mathfrak{p} = (1)$ contradicting primality. Conversely, when $R$ is nontrivial ($\bot \neq \top$), applying \texttt{Ideal.exists\_le\_maximal} yields a maximal ideal $\mathfrak{m} \subset R$, which is prime via \texttt{Ideal.IsMaximal.isPrime}. \texttt{AuditEnv} certifies exact dependence on \texttt{[Classical.choice, Quot.sound, propext]}.
\end{proof}

